import jdk.jfr.consumer.*;
import java.nio.file.*;
import java.time.*;
import java.util.*;

/** Read-only execution-sample split. No method invocation or operation count is inferred. */
public final class SummaryDemandFocus {
    static final String E="org.opentaint.dataflow.bidi.engine.", A="org.opentaint.dataflow.bidi.ap.", S="org.opentaint.dataflow.bidi.store.";
    static final LinkedHashMap<String,String[]> SELECTORS=new LinkedHashMap<>();
    static {
        add("subscribe",E+"SubscriptionManager","subscribe");
        add("replay",E+"SubscriptionManager","replay");
        add("delivery",E+"SubscriptionManager","onDelivery");
        add("apply-match",E+"SubscriptionManager","applyMatch");
        add("record-replay",E+"SubscriptionManager","replayRecords");
        add("publication-index-candidates",E+"PublicationIndex","candidates");
        add("publication-index-publications",E+"PublicationIndex","publications");
        add("publication-index-add",E+"PublicationIndex","addAll");
        add("input-candidates",E+"CalleeSubscriptions","candidates");
        add("diagonal-borrow",S+"DiagonalRelations","borrow");
        add("demand-C2",S+"DemandStore","initials");
        add("demand-C5",S+"DemandStore","intersect");
        add("restrict-raw",A+"DemandKt","restrictRaw");
        add("restrict-plain",A+"DemandKt","restrictPlainFacts");
        add("reference-restrict",A+"ReferenceKt","restrict");
        add("inside-demand",A+"ReferenceKt","insideDemand");
        add("static-pair-walk",S+"StaticPairLookup","walk");
        add("satisfying",A+"SummaryKt","satisfyingPart");
        add("AP-summary-apply",A+"ApOps","applySummary");
        add("call-summary-apply",E+"RunMethodCallServices","applySummary");
        add("call-suffix",E+"RunMethodCallServices","flow");
        add("point-admission",S+"MethodEdgeStore","add");
    }
    static void add(String tag,String owner,String method){SELECTORS.put(tag,new String[]{owner,method});}
    static boolean matches(String frame,String owner,String method){
        int p=frame.lastIndexOf('.'); if(p<0)return false;
        String c=frame.substring(0,p),m=frame.substring(p+1);
        return c.equals(owner)&&(m.equals(method)||m.startsWith(method+"-")||m.equals("access$"+method)||m.startsWith("access$"+method+"-")) || c.startsWith(owner+"$"+method+"$");
    }
    static boolean matches(String frame,String tag){String[]s=SELECTORS.get(tag);return matches(frame,s[0],s[1]);}
    static String nearest(List<String> frames,List<String> tags){
        if(frames!=null)for(String frame:frames)for(String tag:tags)if(matches(frame,tag))return tag;
        return "none";
    }
    static final List<String> ORIGINS=List.of("record-replay","replay","delivery");
    static final List<String> STAGES=List.of("diagonal-borrow","publication-index-publications","publication-index-candidates","input-candidates","reference-restrict","inside-demand","restrict-raw","restrict-plain","static-pair-walk","demand-C2","demand-C5","satisfying","AP-summary-apply","point-admission","call-summary-apply","call-suffix");
    static void inc(Map<String,Long> map,String k){map.merge(k,1L,Long::sum);}
    static List<Object> top(Map<String,Long> map,int max){
        List<Map.Entry<String,Long>> rows=new ArrayList<>(map.entrySet());rows.sort(Map.Entry.<String,Long>comparingByValue().reversed().thenComparing(Map.Entry.comparingByKey()));
        List<Object>out=new ArrayList<>();for(int i=0;i<Math.min(max,rows.size());i++)out.add(Map.of("frame",rows.get(i).getKey(),"events",rows.get(i).getValue()));return out;
    }
    static final class Counts {
        final String label; final CampaignJfrWindow.Window window;
        long samples,withStack,noStack,truncated;
        final Map<String,Long> inclusive=new TreeMap<>(),leaf=new TreeMap<>(),allLeaves=new HashMap<>(),origins=new TreeMap<>(),originStage=new TreeMap<>(),cooccur=new TreeMap<>();
        final Map<String,Map<String,Long>> leavesUnder=new TreeMap<>();
        Counts(String l,Instant s,Instant e){label=l;window=new CampaignJfrWindow.Window(s,e);}
        void add(Instant at,List<String> frames,boolean cut){
            if(!window.contains(at))return;samples++;if(cut)truncated++;
            if(frames==null||frames.isEmpty()){noStack++;return;}withStack++;inc(allLeaves,frames.get(0));
            List<String> hit=new ArrayList<>();
            for(String tag:SELECTORS.keySet()){
                boolean yes=false;for(String frame:frames)if(matches(frame,tag)){yes=true;break;}
                if(!yes)continue;hit.add(tag);inc(inclusive,tag);inc(leavesUnder.computeIfAbsent(tag,k->new HashMap<>()),frames.get(0));
                if(matches(frames.get(0),tag))inc(leaf,tag);
            }
            for(int i=0;i<hit.size();i++)for(int j=i+1;j<hit.size();j++)inc(cooccur,hit.get(i)+" & "+hit.get(j));
            String origin=nearest(frames,ORIGINS);inc(origins,origin);inc(originStage,origin+" / "+nearest(frames,STAGES));
        }
        Object output(){
            Map<String,Object>methods=new LinkedHashMap<>();
            for(String tag:SELECTORS.keySet())methods.put(tag,Map.of("inclusive",inclusive.getOrDefault(tag,0L),"leaf",leaf.getOrDefault(tag,0L),"inclusive_percent",samples==0?0d:100d*inclusive.getOrDefault(tag,0L)/samples,"leaf_percent",samples==0?0d:100d*leaf.getOrDefault(tag,0L)/samples,"top25_leaves_under_inclusive",top(leavesUnder.getOrDefault(tag,Map.of()),25)));
            return CampaignJfrWindow.object("label",label,"start_inclusive",window.start.toString(),"end_exclusive",window.end.toString(),"execution_samples",samples,"with_stack",withStack,"without_stack",noStack,"truncated",truncated,"selectors",methods,"nearest_origin",origins,"nearest_origin_and_stage",originStage,"cooccurrence",cooccur,"top40_leaves",top(allLeaves,40));
        }
    }
    public static void main(String[] args)throws Exception{
        if(args.length<5||(args.length-2)%3!=0)throw new IllegalArgumentException("input output label start end [label start end...]");
        Path input=Path.of(args[0]),output=Path.of(args[1]);if(Files.exists(output))throw new IllegalArgumentException("refuse overwrite");
        long bytes=Files.size(input),mtime=Files.getLastModifiedTime(input).toMillis();String hash;
        try(var in=Files.newInputStream(input)){hash=CampaignJfrWindow.sha256(in);}
        List<Counts>windows=new ArrayList<>();for(int i=2;i<args.length;i+=3)windows.add(new Counts(args[i],Instant.parse(args[i+1]),Instant.parse(args[i+2])));
        Instant first=null,last=null;long scanned=0;
        try(RecordingFile f=new RecordingFile(input)){
            while(f.hasMoreEvents()){
                RecordedEvent e=f.readEvent();Instant at=e.getStartTime();scanned++;
                if(first==null||at.isBefore(first))first=at;if(last==null||at.isAfter(last))last=at;
                if(!e.getEventType().getName().equals("jdk.ExecutionSample"))continue;
                boolean wanted=false;for(Counts w:windows)if(w.window.contains(at)){wanted=true;break;}if(!wanted)continue;
                RecordedStackTrace stack=e.getStackTrace();List<String>frames=CampaignJfrWindow.frames(stack);boolean truncated=stack!=null&&stack.isTruncated();
                for(Counts w:windows)w.add(at,frames,truncated);
            }
        }
        String after;try(var in=Files.newInputStream(input)){after=CampaignJfrWindow.sha256(in);}
        if(!hash.equals(after)||bytes!=Files.size(input)||mtime!=Files.getLastModifiedTime(input).toMillis())throw new IllegalStateException("input changed");
        Map<String,Object>r=new LinkedHashMap<>();r.put("version","summary-demand-methods-v1");r.put("input",input.toString());r.put("input_sha256",hash);r.put("input_bytes",bytes);r.put("scan_first",first.toString());r.put("scan_last",last.toString());r.put("all_events_scanned",scanned);r.put("java_version",System.getProperty("java.version"));Map<String,Object> selectorOutput=new LinkedHashMap<>(); SELECTORS.forEach((k,v)->selectorOutput.put(k,List.of(v))); r.put("selectors",selectorOutput);r.put("windows",windows.stream().map(Counts::output).toList());r.put("limits",List.of("ExecutionSample counts are samples, not calls, invocations, operations, wall time or native GC CPU.","Inclusive selectors and cooccurrences overlap. Each selector counts once per event, even for recursion.","Kotlin generated method classes and access bridges are counted with their source method; overloads and value-class mangling are merged.","Nearest origin/stage is the first selected frame in leaf-to-root order; it separates nested Inline replay from its outer delivery. It does not attribute all CPU or all helpers.","All stack leaves in each selected path are counted; top25 leaf output is capped, but selector counts are complete."));
        Files.writeString(output,CampaignJfrWindow.json(r)+"\n",StandardOpenOption.CREATE_NEW);System.out.println("COMPLETE "+output);
    }
}

