import java.time.*;import java.util.*;
public final class FocusControl{
 static void check(boolean b,String m){if(!b)throw new AssertionError(m);}
 public static void main(String[]args){
  var s=Instant.parse("2026-01-01T00:00:00Z");var c=new SummaryDemandFocus.Counts("control",s,s.plusSeconds(10));
  String seq=SummaryDemandFocus.E+"CalleeSubscriptions$candidates$1.invokeSuspend",delivery=SummaryDemandFocus.E+"SubscriptionManager.onDelivery",replay=SummaryDemandFocus.E+"SubscriptionManager.replay",borrow=SummaryDemandFocus.S+"DiagonalRelations$borrow$1.invokeSuspend";
  c.add(s.minusNanos(1),List.of(delivery),false);c.add(s.plusSeconds(10),List.of(delivery),false);check(c.samples==0,"half-open window");
  c.add(s,List.of(seq,delivery,delivery),false);check(c.samples==1&&c.inclusive.get("delivery")==1&&c.leaf.get("input-candidates")==1,"generated class, recursion and leaf");
  c.add(s.plusSeconds(1),List.of(borrow,replay,delivery),true);check(c.origins.get("replay")==1&&c.inclusive.get("delivery")==2&&c.truncated==1,"nearest nested origin and inclusive overlap");
  c.add(s.plusSeconds(2),null,false);check(c.samples==3&&c.noStack==1&&c.withStack==2,"missing stack denominator");
  check(SummaryDemandFocus.matches(SummaryDemandFocus.E+"PublicationIndex.access$publications","publication-index-publications"),"access bridge");
  check(SummaryDemandFocus.matches(SummaryDemandFocus.E+"PublicationIndex.publications-abc","publication-index-publications"),"mangled value method");
  check(!SummaryDemandFocus.matches(SummaryDemandFocus.E+"PublicationIndex.publicationsOther","publication-index-publications"),"no prefix false positive");
  var empty=new SummaryDemandFocus.Counts("empty",s,s);empty.add(s,List.of(delivery),false);check(empty.samples==0,"empty window");
  System.out.println("PASS7: half-open boundaries; recursion/leaf/generatedclass; nested origins/overlap/truncation; missingstack; bridge; mangling/no falseprefix; emptywindow");
 }
}

source_text.CampaignJfrWindow.java:
import jdk.jfr.consumer.RecordedEvent;
import jdk.jfr.consumer.RecordedFrame;
import jdk.jfr.consumer.RecordedMethod;
import jdk.jfr.consumer.RecordedObject;
import jdk.jfr.consumer.RecordedStackTrace;
import jdk.jfr.consumer.RecordingFile;

import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import java.nio.file.attribute.BasicFileAttributes;
import java.security.MessageDigest;
import java.time.Duration;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;

/** Read-only, single-pass JFR aggregation. No expanded JSON export or dependencies. */
public final class CampaignJfrWindow {
    static final int TOP_LIMIT = 1000;
    static final String VERSION = "fast-jfr-window-v1";
    static final Set<String> SELECTED_TYPES = Set.of("jdk.ExecutionSample", "jdk.ObjectAllocationSample",
            "jdk.GCPhasePause", "jdk.GarbageCollection", "jdk.GCHeapSummary");

    static final class Window {
        final Instant start;
        final Instant end;
        Window(Instant start, Instant end) {
            if (end.isBefore(start)) throw new IllegalArgumentException("end precedes start");
            this.start = start;
            this.end = end;
        }
        boolean contains(Instant time) { return !time.isBefore(start) && time.isBefore(end); }
        long overlapNanos(Instant from, Instant to) {
            Instant lo = from.isBefore(start) ? start : from;
            Instant hi = to.isAfter(end) ? end : to;
            return hi.isAfter(lo) ? Duration.between(lo, hi).toNanos() : 0;
        }
    }

    static final String[] FAMILIES = {"demand-c2", "demand-c5", "demand-total", "static-entry-search", "static-pair-search", "static-call-graph", "call-pipeline", "summary-apply", "summary-match", "initial-admission", "rule-evaluation", "cleaners", "protection", "trie-work", "aliases", "nd-joins", "run1-static-pool", "joined-writer-binding", "AP-interning", "IR-storage", "Spring"};
    static boolean family(String name, String f) {
        return switch (name) {
            case "demand-c2" -> f.startsWith("org.opentaint.dataflow.bidi.store.DemandStore.initials");
            case "demand-c5" -> f.startsWith("org.opentaint.dataflow.bidi.store.DemandStore.intersect");
            case "demand-total" -> f.startsWith("org.opentaint.dataflow.bidi.store.DemandStore.") || f.startsWith("org.opentaint.dataflow.bidi.store.StaticEntryLookup") || f.startsWith("org.opentaint.dataflow.bidi.store.StaticPairLookup") || f.startsWith("org.opentaint.dataflow.bidi.store.FrozenStaticCompletion") || f.startsWith("org.opentaint.dataflow.bidi.store.DetachedStaticCallGraph");
            case "static-entry-search" -> f.startsWith("org.opentaint.dataflow.bidi.store.StaticEntryLookup");
            case "static-pair-search" -> f.startsWith("org.opentaint.dataflow.bidi.store.StaticPairLookup");
            case "static-call-graph" -> f.startsWith("org.opentaint.dataflow.bidi.store.DetachedStaticCallGraph");
            case "call-pipeline" -> f.startsWith("org.opentaint.dataflow.bidi.engine.RunMethodCallServices.");
            case "summary-apply" -> f.startsWith("org.opentaint.dataflow.bidi.ap.ApOps.applySummary");
            case "summary-match" -> f.startsWith("org.opentaint.dataflow.bidi.ap.ApOps.satisfying") || f.endsWith(".matches") && f.startsWith("org.opentaint.dataflow.bidi.engine.");
            case "initial-admission" -> f.startsWith("org.opentaint.dataflow.bidi.engine.RunMethodAnalyzer.addLink") || f.startsWith("org.opentaint.dataflow.bidi.engine.Run1Abstraction");
            case "rule-evaluation" -> f.startsWith("org.opentaint.dataflow.bidi.engine.RunMethodLocalServices.sourcePredicate") || f.startsWith("org.opentaint.dataflow.bidi.engine.RunMethodLocalServices.checkSinks") || f.startsWith("org.opentaint.dataflow.bidi.engine.RunMethodLocalServices.conjunction");
            case "cleaners" -> f.startsWith("org.opentaint.dataflow.bidi.ap.CleanKt.") || f.startsWith("org.opentaint.dataflow.bidi.ap.FlowClean.") || f.startsWith("org.opentaint.dataflow.bidi.ap.TaintClean.") || f.startsWith("org.opentaint.dataflow.bidi.engine.RunMethodCallServices.cleanChain");
            case "protection" -> f.contains("intersectTaintMask") || f.contains("withProtection") || f.contains("protectedPart") || f.contains("protectTarget") || f.contains("ruleProtection");
            case "trie-work" -> f.startsWith("org.opentaint.dataflow.bidi.ap.Trie");
            case "aliases" -> f.contains(".alias.") || f.contains(".aliases.") || f.contains(".bidi.") && (f.contains(".Alias") || f.contains(".alias"));
            case "nd-joins" -> f.contains(".NdSummaryJoin") || f.contains(".KaryJoin") || f.contains(".ConjunctionStore") || f.contains(".RulePredicateStore") || f.contains(".Run1Origin");
            case "run1-static-pool" -> f.contains(".Run1StaticService") || f.contains(".StaticSupplies") || f.contains(".StaticBatch");
            case "joined-writer-binding" -> f.contains(".JoinedStaticWriterBinding") || f.contains(".CalleeSubscriptions.visitJoinedCandidates");
            case "AP-interning" -> f.contains(".bidi.ap.TrieInterner") || f.contains(".bidi.ap.TaintAlgebra.intern") || f.contains(".bidi.ap.ApManager.intern");
            case "IR-storage" -> f.startsWith("org.opentaint.ir.") || f.startsWith("jetbrains.exodus.");
            case "Spring" -> f.startsWith("org.opentaint.jvm.sast.project.spring.");
            default -> throw new IllegalArgumentException(name);
        };
    }
    static final class Count {
        long events;
        long weight;
        void add(long value) { events = Math.addExact(events, 1); weight = Math.addExact(weight, value); }
    }

    static final class FrameStats {
        final String weightUnit;
        long events, withStack, noStack, truncated, missingWeight, negativeWeight, zeroWeight;
        long weight, noStackWeight, frameOccurrences, uniqueFrameMemberships;
        Instant first, last;
        final Map<String, Count> leaf = new HashMap<>();
        final Map<String, Count> inclusive = new HashMap<>();
        final Map<String, Count> families = new HashMap<>();
        final Map<String, Count> leafFamilies = new HashMap<>();
        final Set<String> unique = new HashSet<>(); // scratch only; reset on every event
        FrameStats(String weightUnit) { this.weightUnit = weightUnit; }
        void add(Instant at, List<String> frames, boolean isTruncated, Long offeredWeight) {
            events = Math.addExact(events, 1);
            if (first == null || at.isBefore(first)) first = at;
            if (last == null || at.isAfter(last)) last = at;
            if (isTruncated) truncated = Math.addExact(truncated, 1);
            long value;
            if (offeredWeight == null) { missingWeight++; value = 0; }
            else if (offeredWeight < 0) { negativeWeight++; value = 0; }
            else { value = offeredWeight; if (value == 0) zeroWeight++; }
            weight = Math.addExact(weight, value);
            if (frames == null || frames.isEmpty()) {
                noStack++;
                noStackWeight = Math.addExact(noStackWeight, value);
                return;
            }
            withStack++;
            for (String name : FAMILIES) {
                if (family(name, frames.get(0))) leafFamilies.computeIfAbsent(name, ignored -> new Count()).add(value);
                for (String frame : frames) if (family(name, frame)) {
                    families.computeIfAbsent(name, ignored -> new Count()).add(value);
                    break;
                }
            }
            frameOccurrences = Math.addExact(frameOccurrences, frames.size());
            leaf.computeIfAbsent(frames.get(0), ignored -> new Count()).add(value);
            unique.clear();
            for (String frame : frames) {
                if (unique.add(frame)) {
                    inclusive.computeIfAbsent(frame, ignored -> new Count()).add(value);
                    uniqueFrameMemberships = Math.addExact(uniqueFrameMemberships, 1);
                }
            }
        }
        Map<String, Object> output() {
            return object("eventCount", events, "emptySampleWindow", events == 0, "weightUnit", weightUnit, "weight", weight,
                    "withStackEvents", withStack, "noStackEvents", noStack, "noStackWeight", noStackWeight,
                    "truncatedStackEvents", truncated, "missingWeightEvents", missingWeight,
                    "negativeWeightEvents", negativeWeight, "zeroWeightEvents", zeroWeight,
                    "frameOccurrences", frameOccurrences, "uniqueFrameMemberships", uniqueFrameMemberships,
                    "firstIncludedTimestamp", str(first), "lastIncludedTimestamp", str(last),
                    "leaf", table(leaf), "inclusive", table(inclusive), "familyInclusive", table(families), "familyLeaf", table(leafFamilies));
        }
        Map<String, Object> table(Map<String, Count> counts) {
            List<Map.Entry<String, Count>> entries = new ArrayList<>(counts.entrySet());
            entries.sort(Comparator.<Map.Entry<String, Count>>comparingLong(e -> e.getValue().weight).reversed()
                    .thenComparing(Comparator.<Map.Entry<String, Count>>comparingLong(e -> e.getValue().events).reversed())
                    .thenComparing(Map.Entry::getKey));
            List<Object> rows = new ArrayList<>();
            for (int i = 0; i < Math.min(entries.size(), TOP_LIMIT); i++) {
                Map.Entry<String, Count> entry = entries.get(i);
                Count count = entry.getValue();
                rows.add(object("frame", entry.getKey(), "events", count.events, "weight", count.weight,
                        "eventFraction", fraction(count.events, events), "weightFraction", fraction(count.weight, weight)));
            }
            return object("distinctFrames", entries.size(), "outputRowLimit", TOP_LIMIT,
                    "omittedRows", Math.max(0, entries.size() - TOP_LIMIT), "rows", rows);
        }
    }

    record Interval(Instant start, Instant end) {}
    static final class Durations {
        final Window window;
        long events, zeroDurationEvents, fullNanos, clippedNanos;
        final List<Interval> intervals = new ArrayList<>();
        final Map<String, Long> names = new HashMap<>();
        Durations(Window window) { this.window = window; }
        void add(Instant start, Instant end, String name) {
            long clipped = window.overlapNanos(start, end);
            if (clipped == 0 && !(start.equals(end) && window.contains(start))) return;
            events++;
            if (start.equals(end)) zeroDurationEvents++;
            fullNanos = Math.addExact(fullNanos, Duration.between(start, end).toNanos());
            clippedNanos = Math.addExact(clippedNanos, clipped);
            if (clipped > 0) intervals.add(new Interval(start.isBefore(window.start) ? window.start : start,
                    end.isAfter(window.end) ? window.end : end));
            names.merge(name, 1L, Math::addExact);
        }
        long unionNanos() {
            List<Interval> sorted = new ArrayList<>(intervals);
            sorted.sort(Comparator.comparing(Interval::start).thenComparing(Interval::end));
            long total = 0;
            Instant lo = null, hi = null;
            for (Interval item : sorted) {
                if (lo == null) { lo = item.start; hi = item.end; }
                else if (!item.start.isAfter(hi)) { if (item.end.isAfter(hi)) hi = item.end; }
                else { total = Math.addExact(total, Duration.between(lo, hi).toNanos()); lo = item.start; hi = item.end; }
            }
            return lo == null ? total : Math.addExact(total, Duration.between(lo, hi).toNanos());
        }
        Map<String, Object> output() {
            return object("intersectingEvents", events, "zeroDurationEvents", zeroDurationEvents,
                    "fullEventDurationNanos", fullNanos, "windowClippedDurationSumNanos", clippedNanos,
                    "windowIntervalUnionNanos", unionNanos(), "names", sorted(names));
        }
    }

    static final class HeapStats {
        long events, missingHeapUsed;
        Long min, max, firstValue, lastValue;
        Instant first, last;
        final Map<String, Long> byWhen = new HashMap<>();
        void add(Instant at, String when, Long heapUsed) {
            events++;
            byWhen.merge(when, 1L, Math::addExact);
            if (heapUsed == null) { missingHeapUsed++; return; }
            min = min == null ? heapUsed : Math.min(min, heapUsed);
            max = max == null ? heapUsed : Math.max(max, heapUsed);
            if (first == null || at.isBefore(first)) { first = at; firstValue = heapUsed; }
            if (last == null || at.isAfter(last)) { last = at; lastValue = heapUsed; }
        }
        Map<String, Object> output() {
            return object("events", events, "missingHeapUsedEvents", missingHeapUsed,
                    "byWhen", sorted(byWhen), "minHeapUsedBytes", min, "maxHeapUsedBytes", max,
                    "firstTimestamp", str(first), "firstHeapUsedBytes", firstValue,
                    "lastTimestamp", str(last), "lastHeapUsedBytes", lastValue);
        }
    }

    public static void main(String[] args) throws Exception {
        Map<String, String> options = options(args);
        Path recording = Path.of(required(options, "recording")).toRealPath();
        Path source = Path.of(required(options, "source")).toRealPath();
        Path output = Path.of(required(options, "output")).toAbsolutePath().normalize();
        Window window = new Window(Instant.parse(required(options, "start")), Instant.parse(required(options, "end")));
        if (Files.exists(output)) throw new IllegalArgumentException("Output exists: " + output);
        if (output.equals(recording) || output.equals(source)) throw new IllegalArgumentException("Output is an input");
        String claimedHash = options.get("recording-sha256");
        if (claimedHash != null && !claimedHash.matches("[0-9a-fA-F]{64}"))
            throw new IllegalArgumentException("recording-sha256 must have 64 hexadecimal characters");
        Map<String, Object> before = stat(recording);
        String sourceHash = sha256(Files.newInputStream(source));
        String classHash;
        try (InputStream input = CampaignJfrWindow.class.getResourceAsStream("CampaignJfrWindow.class")) {
            classHash = input == null ? null : sha256(input);
        }
        FrameStats execution = new FrameStats("execution-sample-events");
        FrameStats allocation = new FrameStats("sampled-allocation-weight-bytes");
        Durations pauses = new Durations(window), collections = new Durations(window);
        HeapStats heaps = new HeapStats();
        Map<String, Long> scanned = new HashMap<>(), startsInWindow = new HashMap<>();
        Map<String, Boolean> available = new LinkedHashMap<>();
        for (String name : new java.util.TreeSet<>(SELECTED_TYPES)) available.put(name, false);
        long scannedEvents = 0, includedStarts = 0;
        Instant firstRecorded = null, lastRecorded = null;
        try (RecordingFile file = new RecordingFile(recording)) {
            file.readEventTypes().forEach(type -> { if (available.containsKey(type.getName())) available.put(type.getName(), true); });
            while (file.hasMoreEvents()) {
                RecordedEvent event = file.readEvent();
                scannedEvents++;
