                    }
                    case "jdk.GCPhasePause" -> pauses.add(at, event.getEndTime(), text(event, "name"));
                    case "jdk.GarbageCollection" -> collections.add(at, event.getEndTime(),
                            text(event, "name") + " / " + text(event, "cause"));
                    case "jdk.GCHeapSummary" -> {
                        if (inside) heaps.add(at, text(event, "when"), number(event, "heapUsed"));
                    }
                    default -> throw new AssertionError(type);
