                        "classResourceSha256", classHash, "javaVersion", System.getProperty("java.version"),
                        "compiledSourceBinding", "External javac receipt must bind source hash to class hash"),
                "recording", object("before", before, "after", after,
                        "externallySuppliedSha256", claimedHash == null ? null : claimedHash.toLowerCase(java.util.Locale.ROOT),
                        "sha256VerifiedByReader", false, "binding", "unchanged path/size/mtime/fileKey; optional digest is an external claim"),
                "window", object("startInclusive", window.start.toString(), "endExclusive", window.end.toString(),
                        "durationNanos", Duration.between(window.start, window.end).toNanos(),
                        "emptyWindow", window.start.equals(window.end), "allEventStartsInWindow", includedStarts,
