        System.out.println("CLOSED " + output + " bytes=" + bytes.length + " sha256=" + sha256(Files.newInputStream(output)));
    }

    static List<String> frames(RecordedStackTrace stack) {
        if (stack == null) return null;
        List<String> result = new ArrayList<>(stack.getFrames().size());
        for (RecordedFrame frame : stack.getFrames()) {
            RecordedMethod method = frame.getMethod();
            result.add(method == null ? "<unresolved-frame:" + frame.getType() + ">"
                    : method.getType().getName() + "." + method.getName());
        }
        return result;
    }
    static Long number(RecordedObject event, String field) {
        if (!event.hasField(field)) return null;
        Object value = event.getValue(field);
        return value instanceof Number number ? number.longValue() : null;
    }
    static String text(RecordedObject event, String field) {
        if (!event.hasField(field)) return "<missing>";
        Object value = event.getValue(field);
        return value == null ? "<null>" : value.toString();
    }
    static Map<String, String> options(String[] args) {
        Set<String> accepted = Set.of("recording", "source", "output", "start", "end", "recording-sha256");
        Map<String, String> values = new HashMap<>();
        for (int i = 0; i < args.length; i += 2) {
            if (!args[i].startsWith("--") || i + 1 == args.length) throw new IllegalArgumentException("Expected --key value pairs");
            String key = args[i].substring(2);
            if (!accepted.contains(key) || values.putIfAbsent(key, args[i + 1]) != null)
                throw new IllegalArgumentException("Unknown or duplicate option: " + key);
        }
        return values;
    }
    static String required(Map<String, String> options, String key) {
        String value = options.get(key);
        if (value == null) throw new IllegalArgumentException("Required --" + key);
        return value;
    }
    static Map<String, Object> stat(Path path) throws Exception {
        BasicFileAttributes attrs = Files.readAttributes(path, BasicFileAttributes.class);
        return object("path", path.toString(), "sizeBytes", attrs.size(),
                "modified", attrs.lastModifiedTime().toString(), "fileKey", String.valueOf(attrs.fileKey()));
    }
    static String sha256(InputStream input) throws Exception {
        try (input) {
            MessageDigest digest = MessageDigest.getInstance("SHA-256");
            byte[] buffer = new byte[65536];
            int size;
            while ((size = input.read(buffer)) != -1) digest.update(buffer, 0, size);
            return java.util.HexFormat.of().formatHex(digest.digest());
        }
    }
    static Object fraction(long value, long total) { return total == 0 ? null : (double) value / total; }
    static String str(Instant value) { return value == null ? null : value.toString(); }
    static Map<String, Object> object(Object... pairs) {
        if (pairs.length % 2 != 0) throw new IllegalArgumentException("Odd key/value list");
        Map<String, Object> result = new LinkedHashMap<>();
        for (int i = 0; i < pairs.length; i += 2) result.put((String) pairs[i], pairs[i + 1]);
        return result;
    }
    static Map<String, Long> sorted(Map<String, Long> input) { return new java.util.TreeMap<>(input); }
    static String json(Object value) {
        if (value == null) return "null";
        if (value instanceof Number || value instanceof Boolean) return value.toString();
        if (value instanceof String string) return quote(string);
        if (value instanceof Map<?, ?> map) {
            StringBuilder out = new StringBuilder("{");
            boolean first = true;
            for (Map.Entry<?, ?> entry : map.entrySet()) {
                if (!first) out.append(','); first = false;
                out.append(quote(entry.getKey().toString())).append(':').append(json(entry.getValue()));
            }
            return out.append('}').toString();
        }
        if (value instanceof Iterable<?> items) {
            StringBuilder out = new StringBuilder("[");
            boolean first = true;
            for (Object item : items) { if (!first) out.append(','); first = false; out.append(json(item)); }
            return out.append(']').toString();
        }
        throw new IllegalArgumentException("Cannot encode " + value.getClass());
    }
    static String quote(String value) {
        StringBuilder out = new StringBuilder("\"");
        for (int i = 0; i < value.length(); i++) {
            char ch = value.charAt(i);
            switch (ch) {
                case '"' -> out.append("\\\"");
                case '\\' -> out.append("\\\\");
                case '\n' -> out.append("\\n");
                case '\r' -> out.append("\\r");
                case '\t' -> out.append("\\t");
                default -> { if (ch < 32) out.append(String.format("\\u%04x", (int) ch)); else out.append(ch); }
            }
        }
        return out.append('"').toString();
    }
}

