+package org.opentaint.dataflow.bidi.engine
+
+import java.util.concurrent.atomic.LongAdder
+
+/** Diagnostic-only scalar counts. No facts, keys, paths or trace events are retained. */
+internal object DiagnosticWorkCounters {
+    private const val SIZE = 512
+    private val enabled = java.lang.Boolean.getBoolean("org.opentaint.bidi.workCounters")
+    private val totals = Array(SIZE) { LongAdder() }
+    private val names = Array(SIZE) { "counter$it" }
+    private val local = ThreadLocal.withInitial(::Batch)
+
+    internal class Batch {
+        private val values = LongArray(SIZE)
+        private val dirty = BooleanArray(SIZE)
+        private val touched = IntArray(SIZE)
+        private var touchedSize = 0
+        internal var depth = 0
+        var c5Depth = 0
+        var c2Depth = 0
+        var c5Source = 0
+        var lastOfferFlags = 0
+        var protectionPass = false
+        fun add(code: Int, amount: Long = 1) {
+            if (!dirty[code]) { dirty[code] = true; touched[touchedSize++] = code }
+            values[code] += amount
+        }
+        fun get(code: Int): Long = values[code]
+        internal fun flush() {
+            for (at in 0 until touchedSize) {
+                val code = touched[at]
+                val value = values[code]
+                if (value != 0L) totals[code].add(value)
+                values[code] = 0
+                dirty[code] = false
+            }
+            touchedSize = 0
+        }
+    }
+
+    /** Reserve 0..199 for demand, 200..299 for pub/sub, 300..399 for graph views. */
+    fun register(code: Int, name: String) { synchronized(names) {
+        check(names[code] == "counter$code" || names[code] == name)
+        names[code] = name
+    } }
+    fun begin(): Batch? = if (!enabled) null else local.get().also { it.depth++ }
+    fun end(batch: Batch?) {
+        if (batch == null) return
+        check(batch.depth > 0)
+        if (--batch.depth == 0) batch.flush()
+    }
+    fun current(): Batch? = if (!enabled) null else local.get().takeIf { it.depth > 0 }
+    fun isEnabled(): Boolean = enabled
+    fun reset() {
+        WorkMetric.entries
+        histogramNames(120, "C5_RAW_LEAVES_")
+        histogramNames(140, "C5_PAIR_OFFERS_")
+        histogramNames(160, "C2_ACTUAL_LEAVES_")
+        histogramNames(180, "C2_RETURNED_KEYS_")
+        for (value in totals) value.reset()
+    }
+    fun total(code: Int): Long = totals[code].sum()
+    fun snapshot(): String = totals.indices.filter { totals[it].sum() != 0L }
+        .joinToString(" ") { "${names[it]}=${totals[it].sum()}" }
+
+    fun histogram(batch: Batch?, start: Int, value: Long) {
+        if (batch == null) return
+        val bucket = if (value == 0L) 0 else minOf(19, 64 - java.lang.Long.numberOfLeadingZeros(value))
+        batch.add(start + bucket)
+    }
+    fun histogramNames(start: Int, prefix: String) {
+        register(start, "${prefix}0")
+        for (i in 1..18) register(start + i, "${prefix}${1L shl (i - 1)}to${(1L shl i) - 1}")
+        register(start + 19, "${prefix}262144plus")
+    }
+}
+
+internal enum class WorkMetric {
+    C2_QUERIES, C2_ACTUAL_LEAVES, C2_ENTRY_OFFERS, C2_OFFER_DUPLICATES,
+    C2_EMIT_CHECKS, C2_EMIT_REJECTS, C2_RETURNED_KEYS, C2_HAS_CHECKS, C2_REQUIRE_CHECKS,
+    C5_QUERIES, C5_RAW_LEAVES, C5_PREMISE_MEMBERS, C5_PAIR_OFFERS, C5_NO_EXIT,
+    C5_LOCAL_OFFERS, C5_PRIMITIVE_OFFERS, C5_LOCAL_BFS_OFFERS, C5_VISIBLE_BFS_OFFERS,
+    C5_RESTRICT_CALLS, C5_PROTECTION_PASSES, C5_ORDINARY_PASSES, C5_SCALAR_RESTRICT,
+    C5_SCALAR_PROTECTED, C5_SCALAR_ORDINARY, C5_REJECT_INITIAL_GEOMETRY, C5_REJECT_INITIAL_MARK,
+    C5_REJECT_TARGET_MARK, C5_REJECT_TARGET_BASE, C5_REJECT_TARGET_GEOMETRY, C5_REJECT_NO_EXIT,
+    C5_SCALAR_ACCEPTED, C5_RESULT_PACKETS,
+    C5_BFS_WALKS, C5_BFS_MEMBERS, C5_BFS_ENDPOINT_GATE_REJECTED, C5_BFS_STATES_ATTEMPTED,
+    C5_BFS_STATES_ADMITTED, C5_BFS_STATES_DUPLICATE, C5_BFS_STATES_POPPED,
+    C5_BFS_ENTRY_GEOMETRY_BAD, C5_BFS_ENTRY_MARK_BAD, C5_BFS_FIXED_MAPPED_OUTPUT_MARK_BAD, C5_BFS_OUTPUT_MISMATCH,
+    C5_BFS_STATIC_BRIDGES, C5_BFS_BRIDGES_AFTER_FIXED_ENTRY_REJECT, C5_BFS_OUTPUT_MISMATCH_STATIC_BRIDGES,
+    C5_BFS_COMPOSE_ATTEMPTS, C5_BFS_COMPOSE_SUCCEEDED, C5_BFS_COVERED_STOPS;
+    init { DiagnosticWorkCounters.register(ordinal, name) }
+}
+
+internal fun DiagnosticWorkCounters.Batch.add(metric: WorkMetric, amount: Long = 1) = add(metric.ordinal, amount)
+internal fun DiagnosticWorkCounters.Batch.get(metric: WorkMetric): Long = get(metric.ordinal)
+
+internal object RestrictFlags {
+    const val INITIAL_GEOMETRY = 1
+    const val INITIAL_MARK = 2
+    const val TARGET_MARK = 4
+    const val TARGET_BASE = 8
+    const val TARGET_GEOMETRY = 16
+    const val ACCEPTED = 32
+    const val NO_EXIT = 64
+}
