+    SUMMARY_APPLIER_CALLS, STATIC_CONTROL_APPLIER_CALLS,
+    INDEX_ADDED_OFFERS, INDEX_ADDED_FRESH, INDEX_ADDED_OUTPUTS,
+    INDEX_QUERY_ZERO, INDEX_QUERY_FLOW, INDEX_QUERY_TAINT, SUBSCRIBE_ZERO_FRESH,
+    RECORD_REPLAY_CALLS, RECORD_ENTRY_CANDIDATES, RECORD_NATIVE_SKIPPED,
+    RECORD_NATIVE_MATCH_ATTEMPTS, RECORD_NATIVE_MATCH_SUCCESSES, RECORD_NATIVE_MATCH_REJECTED,
+    RECORD_EXIT_CANDIDATES, RECORD_VIEW_MATCH_ATTEMPTS, RECORD_VIEW_MATCH_SUCCESSES, RECORD_VIEW_MATCH_REJECTED;
+
+    val code get() = 200 + ordinal
+    init {
+        check(200 + ordinal < 250)
+        DiagnosticWorkCounters.register(200 + ordinal, "PS_$name")
+    }
+}
+
+internal fun DiagnosticWorkCounters.Batch.add(metric: PubSubWorkMetric, amount: Long = 1) = add(metric.code, amount)
+
+internal object PubSubWorkHistograms {
+    const val OUTPUTS_PER_GEOMETRIC_MEMBER = 250
+    const val INPUTS_PER_PUBLICATION_MEMBER = 270
+    init {
+        DiagnosticWorkCounters.histogramNames(OUTPUTS_PER_GEOMETRIC_MEMBER, "PS_OUTPUT_FANOUT_")
+        DiagnosticWorkCounters.histogramNames(INPUTS_PER_PUBLICATION_MEMBER, "PS_INPUT_FANOUT_")
+    }
+    fun add(batch: DiagnosticWorkCounters.Batch?, start: Int, value: Long) {
+        if (batch == null) return
+        DiagnosticWorkCounters.histogram(batch, start, value)
+    }
+}
