+package org.opentaint.dataflow.bidi
+
+import org.opentaint.dataflow.ap.ifds.AccessPathBase
+import org.opentaint.dataflow.ap.ifds.ClassStaticAccessor
+import org.opentaint.dataflow.bidi.ap.*
+import org.opentaint.dataflow.bidi.engine.*
+import org.opentaint.dataflow.bidi.fixtures.StoreFixtures
+import org.opentaint.dataflow.bidi.store.*
+import kotlin.test.*
+
+/** Fresh controls for the external, opt-in counter patch. No inference rule is replaced. */
+class DiagnosticDemandWorkCountersTest {
+    private fun total(metric: WorkMetric) = DiagnosticWorkCounters.total(metric.ordinal)
+
+    @Test fun `nested batches flush touched numeric counters after exceptional completion`() {
+        assertTrue(DiagnosticWorkCounters.isEnabled(), "The counter test init script must enable the flag before JVM startup")
+        DiagnosticWorkCounters.reset()
+        DiagnosticWorkCounters.register(510, "CONTROL_A")
+        DiagnosticWorkCounters.register(511, "CONTROL_B")
+        val outer = DiagnosticWorkCounters.begin()!!
+        try {
+            outer.add(510, 3)
+            val inner = DiagnosticWorkCounters.begin()!!
+            assertSame(outer, inner)
+            try { inner.add(511, 2) } finally { DiagnosticWorkCounters.end(inner) }
+            assertEquals(0L, DiagnosticWorkCounters.total(510))
+            assertEquals(0L, DiagnosticWorkCounters.total(511))
+            assertFailsWith<IllegalStateException> { error("bounded control") }
+        } finally { DiagnosticWorkCounters.end(outer) }
+        assertEquals(3L, DiagnosticWorkCounters.total(510))
+        assertEquals(2L, DiagnosticWorkCounters.total(511))
+        val next = DiagnosticWorkCounters.begin()!!
+        try { next.add(510, 1) } finally { DiagnosticWorkCounters.end(next) }
+        assertEquals(4L, DiagnosticWorkCounters.total(510), "Dirty codes reset between scopes")
+    }
+
+    @Test fun `scalar restriction rejection counters partition the actual existing checks`() {
+        val f = StoreFixtures()
+        val a = AccessPathBase.Argument(0)
+        val b = AccessPathBase.Return
+        val t = MarkSlot.Concrete(f.mark("T"))
+        val u = MarkSlot.Concrete(f.mark("U"))
+        val p = f.pattern(a, mark = t)
+        val q = f.pattern(b, mark = t)
+        val result = Conclusion(q.fact, ExclusionSet.Empty, false)
+        DiagnosticWorkCounters.reset()
+        val batch = DiagnosticWorkCounters.begin()!!
+        batch.c5Depth++
+        try {
+            assertNull(restrict(p, result, DemandPattern(p, null), f.manager.marks))
+            assertNull(restrict(p.copy(fact = p.fact.copy(tail = Tail.STAR)), result,
+                DemandPattern(p, q), f.manager.marks))
+            assertNull(restrict(p, result, DemandPattern(p.copy(fact = p.fact.copy(mark = u)), q), f.manager.marks))
+            assertNull(restrict(p, result.copy(fact = result.fact.copy(mark = u)), DemandPattern(p, q), f.manager.marks))
+            assertNull(restrict(p, result, DemandPattern(p, p), f.manager.marks))
+            assertNull(restrict(p, result.copy(fact = result.fact.copy(path = listOf(f.field("f")))),
+                DemandPattern(p, q.copy(fact = q.fact.copy(path = listOf(f.field("g"))))), f.manager.marks))
+            assertEquals(result, restrict(p, result, DemandPattern(p, q), f.manager.marks))
+        } finally { batch.c5Depth--; DiagnosticWorkCounters.end(batch) }
+        assertEquals(7L, total(WorkMetric.C5_SCALAR_RESTRICT))
+        assertEquals(1L, total(WorkMetric.C5_REJECT_NO_EXIT))
+        assertEquals(1L, total(WorkMetric.C5_REJECT_INITIAL_GEOMETRY))
+        assertEquals(1L, total(WorkMetric.C5_REJECT_INITIAL_MARK))
+        assertEquals(1L, total(WorkMetric.C5_REJECT_TARGET_MARK))
+        assertEquals(1L, total(WorkMetric.C5_REJECT_TARGET_BASE))
+        assertEquals(1L, total(WorkMetric.C5_REJECT_TARGET_GEOMETRY))
+        assertEquals(1L, total(WorkMetric.C5_SCALAR_ACCEPTED))
+    }
+
+    @Test fun `C2 counts actual scalar leaves but collapses entries across paired exits`() {
+        val f = StoreFixtures()
+        val a = AccessPathBase.Argument(0)
+        val entry = f.pattern(a, tail = Tail.STAR, mark = MarkSlot.STAR)
+        val store = DemandStore.Builder(f.manager).apply {
+            add(f.method, DemandPattern(entry, f.pattern(AccessPathBase.Return, tail = Tail.STAR, mark = MarkSlot.STAR)))
+            add(f.method, DemandPattern(entry, f.pattern(AccessPathBase.Argument(1), tail = Tail.STAR, mark = MarkSlot.STAR)))
+        }.build()
+        val input = f.manager.mergeAddDelta(f.fact(a), f.fact(a, mark = MarkSlot.Concrete(f.mark("U")))).first
+        DiagnosticWorkCounters.reset()
+        assertEquals(setOf(f.manager.initial(entry)), store.initials(f.method, input))
+        assertEquals(1L, total(WorkMetric.C2_QUERIES))
+        assertEquals(2L, total(WorkMetric.C2_ACTUAL_LEAVES))
+        assertEquals(2L, total(WorkMetric.C2_ENTRY_OFFERS))
+        assertEquals(2L, total(WorkMetric.C2_EMIT_CHECKS))
+        assertEquals(1L, total(WorkMetric.C2_RETURNED_KEYS))
+    }
+
+    @Test fun `C5 counts both scalar protection passes without changing the protected answer`() {
+        val f = StoreFixtures()
+        val a = AccessPathBase.Argument(0)
+        val b = AccessPathBase.Return
+        val entry = f.pattern(a, tail = Tail.STAR, mark = MarkSlot.STAR)
+        val target = f.pattern(b, tail = Tail.STAR, mark = MarkSlot.STAR)
+        val store = DemandStore.Builder(f.manager).apply { add(f.method, DemandPattern(entry, target)) }.build()
+        val raw = (f.manager.mergeAddDelta(f.fact(b), f.fact(b, mark = MarkSlot.Concrete(f.mark("U")))).first as TaintTree)
+            .let { it.withProtection(it.root) }
+        val initial = f.manager.initial(f.pattern(a))
+        DiagnosticWorkCounters.reset()
+        val kept = store.intersect(f.method, initial, raw)
+        assertEquals(listOf(raw), kept)
+        assertTrue((kept.single() as TaintTree).nonSubsumable != null)
+        assertEquals(1L, total(WorkMetric.C5_QUERIES))
+        assertEquals(2L, total(WorkMetric.C5_RAW_LEAVES))
+        assertEquals(1L, total(WorkMetric.C5_RESTRICT_CALLS))
+        assertEquals(2L, total(WorkMetric.C5_SCALAR_PROTECTED))
+        assertEquals(2L, total(WorkMetric.C5_SCALAR_ORDINARY))
+        assertEquals(4L, total(WorkMetric.C5_SCALAR_RESTRICT))
+    }
+
+    private fun bridgeCase(exactReader: Boolean): Pair<List<Facts>, Map<WorkMetric, Long>> {
+        val f = StoreFixtures()
+        val a = AccessPathBase.Argument(0)
+        val b = AccessPathBase.Return
+        val cls = f.manager.accessors.index(ClassStaticAccessor("C"))
+        val t = MarkSlot.Concrete(f.mark("T"))
+        val writer = f.pattern(a, tail = Tail.STAR, mark = t)
+        val static = f.pattern(STATIC, listOf(cls, f.field("f")), Tail.STAR, t)
+        val reader = f.pattern(b, tail = if (exactReader) Tail.EXACT else Tail.STAR, mark = t)
+        val graph = DetachedStaticCallGraph.copyOf(mapOf(f.commonMethod to emptySet()), f.cancellation)
+        val completion = FrozenStaticCompletion.Builder(f.manager, graph).apply {
+            addSeed(f.method, StaticGuidanceEdge.of(writer, static))
+            addSeed(f.method, StaticGuidanceEdge.of(static, reader))
+        }.build()
+        val store = DemandStore.Builder(f.manager).apply { withCompletion(completion) }.build()
+        val initial = f.manager.initial(f.pattern(b, tail = Tail.STAR, mark = t))
+        val raw = f.fact(a, tail = Tail.STAR, mark = t, layer = Layer.DEMAND)
+        DiagnosticWorkCounters.reset()
+        val result = store.intersect(f.method, initial, raw)
+        return result to WorkMetric.entries.associateWith(::total)
+    }
+
+    @Test fun `BFS separates fixed entry rejection from a mismatched output that needs a static bridge`() {
+        val (rejected, bad) = bridgeCase(exactReader = true)
