+/** External diagnostic controls. The test JVM must start with workCounters=true. */
+class GraphWorkCountersTest {
+    private fun count(metric: GraphWorkMetric): Long = DiagnosticWorkCounters.snapshot()
+        .split(' ').mapNotNull { token -> token.split('=').takeIf { it.size == 2 } }
+        .associate { it[0] to it[1].toLong() }[metric.name] ?: 0L
+
+    @Test
+    fun `incremental reachability keeps its answers and counts repeated root scratch`() {
+        DiagnosticWorkCounters.reset()
+        val f = EngineShellFixtures()
+        val graph = DetachedStaticCallGraph.copyOf(linkedMapOf(
+            f.methodA to setOf(f.methodB),
+            f.methodB to setOf(f.methodUnknown),
+            f.methodUnknown to emptySet(),
+        ), f.cancellation)
+        val batch = assertNotNull(DiagnosticWorkCounters.begin())
+        batch.c2Depth++
+        try {
+            val first = graph.scratch(f.methodA, f.cancellation)
+            assertTrue(first.reachesAny(intArrayOf(2)))
+            assertTrue(first.reachesAny(intArrayOf(1)))
+            assertFalse(first.reachesAny(intArrayOf(99)))
+            assertFalse(first.reachesAny(intArrayOf()))
+            val second = graph.scratch(f.methodA, f.cancellation)
+            assertFalse(second.reachesAny(intArrayOf()))
+        } finally {
+            batch.c2Depth--
+            DiagnosticWorkCounters.end(batch)
+        }
+        assertEquals(2L, count(GraphWorkMetric.CG_SCRATCH_CREATED))
+        assertEquals(2L, count(GraphWorkMetric.CG_C2_SCRATCH_CREATED))
+        assertEquals(1L, count(GraphWorkMetric.CG_UNIQUE_ROOTS_GRAPH_LIFETIME))
+        assertEquals(1L, count(GraphWorkMetric.CG_REPEATED_ROOT_SCRATCH))
+        assertEquals(5L, count(GraphWorkMetric.CG_REACHES_ANY_CALLS))
+        assertEquals(5L, count(GraphWorkMetric.CG_C2_REACHES_ANY_CALLS))
+        assertEquals(3L, count(GraphWorkMetric.CG_OWNER_IDS_OFFERED))
+        assertEquals(3L, count(GraphWorkMetric.CG_OWNER_MEMBERSHIP_TESTS))
+        assertEquals(2L, count(GraphWorkMetric.CG_EMPTY_OWNER_CALLS))
+        assertEquals(1L, count(GraphWorkMetric.CG_ENTRY_SEEN_HITS))
+        assertEquals(1L, count(GraphWorkMetric.CG_TRAVERSAL_HITS))
+        assertEquals(3L, count(GraphWorkMetric.CG_EXHAUSTED_CALLS))
+        assertEquals(6L, count(GraphWorkMetric.CG_VERTICES_EXPANDED))
+        assertEquals(4L, count(GraphWorkMetric.CG_EDGES_EXAMINED))
+        assertEquals(6L, count(GraphWorkMetric.CG_NEW_VERTICES))
+        assertEquals(4L, count(GraphWorkMetric.CG_OWNER_SEARCHES))
+        assertEquals(0L, count(GraphWorkMetric.CG_SEEN_EDGES))
+    }
+
+    @Test
+    fun `new visible views repeat graph work while a current view uses its seen vertices`() {
+        DiagnosticWorkCounters.reset()
+        val f = EngineShellFixtures()
+        val graph = DetachedStaticCallGraph.copyOf(linkedMapOf(
+            f.methodA to setOf(f.methodB), f.methodB to emptySet(),
+        ), f.cancellation)
+        val cls = f.manager.accessors.index(ClassStaticAccessor("C"))
+        fun field(name: String) = Pattern(PathFact(STATIC, listOf(cls, f.field(name)),
+            Tail.STAR, MarkSlot.STAR), ExclusionSet.Empty)
+        val target = field("g")
+        val completion = FrozenStaticCompletion.Builder(f.manager, graph).apply {
+            addSeed(f.b, field("f"), target)
+        }.build()
+        val batch = assertNotNull(DiagnosticWorkCounters.begin())
+        batch.c5Depth++
+        try {
+            assertTrue(completion.local(f.a).entries(target).toList().isEmpty())
+            val first = completion.visible(f.a)
+            assertEquals(listOf(target), first.entries(target).toList())
+            assertEquals(listOf(target), first.entries(target).toList())
+            assertEquals(listOf(target), completion.visible(f.a).entries(target).toList())
+        } finally {
+            batch.c5Depth--
+            DiagnosticWorkCounters.end(batch)
+        }
+        assertEquals(1L, count(GraphWorkMetric.CG_LOCAL_VIEWS))
+        assertEquals(2L, count(GraphWorkMetric.CG_VISIBLE_VIEWS))
+        assertEquals(1L, count(GraphWorkMetric.CG_C5_LOCAL_VIEWS))
+        assertEquals(2L, count(GraphWorkMetric.CG_C5_VISIBLE_VIEWS))
+        assertEquals(2L, count(GraphWorkMetric.CG_SCRATCH_CREATED))
+        assertEquals(1L, count(GraphWorkMetric.CG_UNIQUE_ROOTS_GRAPH_LIFETIME))
+        assertEquals(1L, count(GraphWorkMetric.CG_REPEATED_ROOT_SCRATCH))
+        assertEquals(1L, count(GraphWorkMetric.CG_LOCAL_ELIGIBILITY_CALLS))
+        assertEquals(3L, count(GraphWorkMetric.CG_VISIBLE_ELIGIBILITY_CALLS))
+        assertEquals(3L, count(GraphWorkMetric.CG_ELIGIBLE_RESULTS))
+        assertEquals(1L, count(GraphWorkMetric.CG_INELIGIBLE_RESULTS))
+        assertEquals(1L, count(GraphWorkMetric.CG_ENTRY_SEEN_HITS))
+        assertEquals(2L, count(GraphWorkMetric.CG_TRAVERSAL_HITS))
+        assertEquals(2L, count(GraphWorkMetric.CG_VERTICES_EXPANDED))
+        assertEquals(2L, count(GraphWorkMetric.CG_EDGES_EXAMINED))
+    }
+}
