+/** External diagnostic controls. Launch this fork with org.opentaint.bidi.workCounters=true. */
+class PubSubWorkCountersTest {
+    private fun snapshot(): Map<String, Long> = DiagnosticWorkCounters.snapshot().split(' ')
+        .filter { '=' in it }.associate { value -> value.substringBefore('=') to value.substringAfter('=').toLong() }
+    private fun Map<String, Long>.count(name: String) = getOrDefault("PS_$name", 0)
+    private fun <T> measured(body: () -> T): T {
+        val batch = assertNotNull(DiagnosticWorkCounters.begin(), "Enable the external work-counter property")
+        try { return body() } finally { DiagnosticWorkCounters.end(batch) }
+    }
+
+    @Test
+    fun `replay counters count existing geometric expansion and exact predicate outcomes`() {
+        PipelineFixtures(index = 3).use { f ->
+            val marks = (0..2).map { MarkSlot.Concrete(f.store.mark("T$it")) }
+            val pubs = marks.flatMap { mark ->
+                val initial = f.ap.initial(f.store.pattern(mark = mark))
+                (1..2).map { output -> Publication(initial, f.store.fact(base = AccessPathBase.Argument(output), mark = mark)) }
+            }
+            f.storage().publish(pubs)
+            DiagnosticWorkCounters.reset()
+            marks.forEachIndexed { index, mark -> f.subscriptions.subscribe(f.subscription(f.store.fact(mark = mark), call = index + 1)) }
+            val counts = snapshot()
+            assertEquals(3L, counts.count("SUBSCRIBE_CALLS"))
+            assertEquals(3L, counts.count("REPLAY_CALLS"))
+            assertEquals(9L, counts.count("INDEX_GEOMETRIC_MEMBERS"))
+            assertEquals(18L, counts.count("INDEX_OUTPUT_PACKETS"))
+            assertEquals(18L, counts.count("REPLAY_MATCH_ATTEMPTS"))
+            assertEquals(6L, counts.count("REPLAY_MATCH_SUCCESSES"))
+            assertEquals(12L, counts.count("REPLAY_MATCH_REJECTED"))
+            assertEquals(6L, counts.count("SUMMARY_APPLIER_CALLS"))
+            assertEquals(9L, counts.count("OUTPUT_FANOUT_2to3"))
+            assertEquals(6, f.summaries.size, "The diagnostic keeps the original successful applications")
+            assertNull(DiagnosticWorkCounters.current())
+        }
+    }
+
+    @Test
+    fun `delivery counters count current input snapshots once per publication member`() {
+        PipelineFixtures(index = 3).use { f ->
+            val marks = (0..2).map { MarkSlot.Concrete(f.store.mark("T$it")) }
+            marks.forEachIndexed { index, mark -> f.subscriptions.subscribe(f.subscription(f.store.fact(mark = mark), call = index + 1)) }
+            val pubs = marks.flatMap { mark ->
+                val initial = f.ap.initial(f.store.pattern(mark = mark))
+                (1..2).map { output -> Publication(initial, f.store.fact(base = AccessPathBase.Argument(output), mark = mark)) }
+            }
+            DiagnosticWorkCounters.reset()
+            f.storage().publish(pubs)
+            f.deliverAll()
+            val counts = snapshot()
+            assertEquals(1L, counts.count("DELIVERY_BATCHES"))
+            assertEquals(6L, counts.count("DELIVERY_PUB_PACKETS"))
+            assertEquals(6L, counts.count("DELIVERY_MEMBERS"))
+            assertEquals(18L, counts.count("INPUT_INDEX_HANDLES"))
+            assertEquals(18L, counts.count("INPUT_INDEX_SNAPSHOTS"))
+            assertEquals(18L, counts.count("DELIVERY_CANDIDATES"))
+            assertEquals(18L, counts.count("DELIVERY_MATCH_ATTEMPTS"))
+            assertEquals(6L, counts.count("DELIVERY_MATCH_SUCCESSES"))
+            assertEquals(12L, counts.count("DELIVERY_MATCH_REJECTED"))
+            assertEquals(6L, counts.count("INPUT_FANOUT_2to3"))
+            assertEquals(6, f.summaries.size)
+            assertNull(DiagnosticWorkCounters.current())
+        }
+    }
+
+    @Test
+    fun `diagonal borrow counts actual scopes and decoded matches without changing its result`() {
+        val f = StoreFixtures()
+        val store = DiagonalRelations(f.manager)
