+        val initials = (0..2).map { index ->
+            val initial = f.manager.initial(f.pattern(base = AccessPathBase.Argument(index), tail = Tail.STAR, mark = mark))
+            assertNotNull(store.add(initial, f.fact(base = AccessPathBase.Return, tail = Tail.STAR, mark = mark)))
+            initial
+        }
+        DiagnosticWorkCounters.reset()
+        val results = measured { store.borrow(initials[0]).toList() }
+        val counts = snapshot()
+        assertEquals(1, results.size)
+        assertEquals(1L, counts.count("DIAGONAL_BORROW_QUERIES"))
+        assertEquals(3L, counts.count("DIAGONAL_SCOPES_VISITED"))
+        assertEquals(1L, counts.count("DIAGONAL_SCOPES_MATCHED"))
+        assertEquals(1L, counts.count("DIAGONAL_GEOMETRY_ROWS"))
+        assertEquals(1L, counts.count("DIAGONAL_MARK_MATCHED"))
+        assertNull(DiagnosticWorkCounters.current())
+    }
+
+    @Test
+    fun `unconsumed and partially consumed sequences do not leak a diagnostic scope`() {
+        val f = StoreFixtures()
+        val store = DiagonalRelations(f.manager)
+        val mark = MarkSlot.Concrete(f.mark("T"))
+        val initial = f.manager.initial(f.pattern(tail = Tail.STAR, mark = mark))
+        assertNotNull(store.add(initial, f.fact(base = AccessPathBase.Return, tail = Tail.STAR, mark = mark)))
+        DiagnosticWorkCounters.reset()
