"""Finite source-model control only; no production cache or analyzer run."""
import itertools
import json


class Reach:
    def __init__(self, root, graph):
        self.graph = graph
        self.seen = set() if root is None else {root}
        self.pending = [] if root is None else [root]

    def query(self, owners):
        if any(owner in self.seen for owner in owners):
            return True
        while self.pending:
            at = self.pending.pop()
            hit = False
            for child in self.graph[at]:
                if child not in self.seen:
                    self.seen.add(child)
                    self.pending.append(child)
                if child in owners:
                    hit = True
            if hit:
                return True
        return False


class View:
    def __init__(self, root, graph, memo):
        self.root = root
        self.graph = graph
        self.reach = None
        self.memo = {} if memo else None

    def query(self, family, owners, outside):
        if self.memo is not None and family in self.memo:
            return self.memo[family]
        if outside:
            result = True
        else:
            if self.reach is None:
                self.reach = Reach(self.root, self.graph)
            result = self.reach.query(owners)
        if self.memo is not None:
            self.memo[family] = result
        return result

    def state(self):
        return None if self.reach is None else (self.reach.seen.copy(), self.reach.pending.copy())


def main():
    size = 3
    owners = [tuple(i for i in range(size) if mask & (1 << i)) for mask in range(1 << size)]
    cases = 0
    calls = 0
    for mask in range(1 << (size * size)):
        graph = [tuple(j for j in range(size) if mask & (1 << (i * size + j))) for i in range(size)]
        for root in [None, 0, 1, 2]:
            for left, right in itertools.product(owners, repeat=2):
                for outside_a, outside_b in itertools.product((False, True), repeat=2):
                    plain = View(root, graph, False)
                    memo = View(root, graph, True)
                    for family, values, outside in [(0, left, outside_a), (1, right, outside_b),
                                                    (0, left, outside_a)]:
                        assert plain.query(family, values, outside) == memo.query(family, values, outside)
                        assert plain.state() == memo.state()
                        calls += 1
                    cases += 1
    print(json.dumps({'status': 'PASS', 'graphs': 512, 'roots': 4, 'owner_subsets': 8,
                      'sequences': cases, 'query_result_and_state_comparisons': calls,
                      'scope': 'All three-vertex directed graphs, including self edges; A,B,A immutable owner families; outsideGraph shortcuts and unknown roots; source-model only.'}))


if __name__ == '__main__':
    main()
